{
  "name": "Xspress3 X射线能谱探测系统",
  "name_en": "Xspress3 X-ray spectroscopy detector system",
  "manufacturer": "",
  "description": "用于X射线荧光或能谱实验的Xspress3探测与读出系统，可进行触发控制、时间序列采集、ROI管理以及数据文件保存。",
  "description_en": "An Xspress3 detection and readout system for X-ray fluorescence or spectroscopy experiments, supporting trigger control, time-series capture, ROI management, and data file saving.",
  "tag_hints": [
    "X-ray spectroscopy",
    "X-ray fluorescence detection",
    "ROI acquisition",
    "external triggering",
    "time series capture",
    "areaDetector file output"
  ],
  "actions": [
    {
      "action_name": "auto-TimeSeriesCaptureOff",
      "description": "关闭时间序列采集",
      "description_en": "turn off time-series capture"
    },
    {
      "action_name": "auto-TimeSeriesCaptureOn",
      "description": "开启时间序列采集",
      "description_en": "turn on time-series capture"
    },
    {
      "action_name": "auto-restore_rois",
      "description": "从 ROI.dat 文件恢复 ROI 设置",
      "description_en": "restore ROI settings from an ROI.dat file"
    },
    {
      "action_name": "auto-roi_calib_info",
      "description": "获取 ROI 校准信息",
      "description_en": "get ROI calibration information"
    },
    {
      "action_name": "auto-filePut",
      "description": "通过文件接口写入文件",
      "description_en": "write a file through the file interface"
    },
    {
      "action_name": "auto-fileGet",
      "description": "通过文件接口读取文件",
      "description_en": "read a file through the file interface"
    },
    {
      "action_name": "auto-setFilePath",
      "description": "设置文件保存路径",
      "description_en": "set the file save path"
    },
    {
      "action_name": "auto-setFileTemplate",
      "description": "设置文件名模板",
      "description_en": "set the file name template"
    },
    {
      "action_name": "auto-setFileWriteMode",
      "description": "设置文件写入模式",
      "description_en": "set the file write mode"
    },
    {
      "action_name": "auto-setFileName",
      "description": "设置文件名",
      "description_en": "set the file name"
    },
    {
      "action_name": "auto-nextFileNumber",
      "description": "递增到下一个文件编号",
      "description_en": "advance to the next file number"
    },
    {
      "action_name": "auto-setFileNumber",
      "description": "设置文件编号",
      "description_en": "set the file number"
    },
    {
      "action_name": "auto-getLastFileName",
      "description": "获取最近生成的文件名",
      "description_en": "get the last generated file name"
    },
    {
      "action_name": "auto-FileCaptureOn",
      "description": "开启文件捕获",
      "description_en": "turn on file capture"
    },
    {
      "action_name": "auto-FileCaptureOff",
      "description": "关闭文件捕获",
      "description_en": "turn off file capture"
    },
    {
      "action_name": "auto-setFileNumCapture",
      "description": "设置文件捕获数量",
      "description_en": "set the number of captures for file output"
    },
    {
      "action_name": "auto-FileWriteComplete",
      "description": "检查文件写入是否完成",
      "description_en": "check whether file writing is complete"
    },
    {
      "action_name": "auto-getFileTemplate",
      "description": "获取文件名模板",
      "description_en": "get the file name template"
    },
    {
      "action_name": "auto-getFileName",
      "description": "获取文件名",
      "description_en": "get the file name"
    },
    {
      "action_name": "auto-getFileNumber",
      "description": "获取文件编号",
      "description_en": "get the file number"
    },
    {
      "action_name": "auto-getFilePath",
      "description": "获取文件保存路径",
      "description_en": "get the file save path"
    },
    {
      "action_name": "auto-getFileNameByIndex",
      "description": "按索引获取文件名",
      "description_en": "get a file name by index"
    },
    {
      "action_name": "auto-useExternalTrigger",
      "description": "切换为外部触发",
      "description_en": "use external trigger mode"
    },
    {
      "action_name": "auto-useInternalTrigger",
      "description": "切换为内部触发",
      "description_en": "use internal trigger mode"
    },
    {
      "action_name": "auto-setTriggerMode",
      "description": "设置触发模式",
      "description_en": "set the trigger mode"
    },
    {
      "action_name": "auto-get_rois",
      "description": "获取已配置的 ROI",
      "description_en": "get configured ROIs"
    },
    {
      "action_name": "auto-select_rois_to_save",
      "description": "选择要保存的 ROI",
      "description_en": "select which ROIs to save"
    }
  ]
}

